<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Expenses</title><style>body{font:15px Arial;background:#f4f6fa;color:#172b43}.wrap{max-width:1150px;margin:30px auto}.card{background:#fff;padding:22px;border-radius:12px;margin:16px 0}input,select{padding:10px;margin:4px;border:1px solid #ccd5df;border-radius:6px}button,a{background:#173d65;color:white;padding:10px 14px;border:0;border-radius:7px;text-decoration:none;cursor:pointer}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:11px;border-bottom:1px solid #eee}</style></head><body><main class="wrap"><h1>Expenses & Cash Outflow</h1><p><a href="{{ route('dashboard') }}">Dashboard</a> <a href="{{ route('reports.index') }}">Reports</a></p>@if(session('success'))<p>{{ session('success') }}</p>@endif<div class="card"><h2>Record Expense</h2><form method="POST" action="{{ route('expenses.store') }}">@csrf@if(auth()->user()->hasRole('owner'))<select name="branch_id" required><option value="">Branch</option>@foreach($branches as $b)<option value="{{ $b->id }}">{{ $b->name }}</option>@endforeach</select>@else<input type="hidden" name="branch_id" value="{{ auth()->user()->branch_id }}">@endif<input name="category" required placeholder="Category (Rent, Utilities...)"><input name="description" required placeholder="Description"><input type="number" min=".01" step=".01" name="amount" required placeholder="Amount PKR"><select name="payment_method"><option value="cash">Cash</option><option value="card">Card</option><option value="bank_transfer">Bank transfer</option><option value="mobile_wallet">Mobile wallet</option><option value="other">Other</option></select><input name="reference" placeholder="Reference"><input type="date" name="expense_date" value="{{ now()->toDateString() }}" required><button>Save Expense</button></form>@foreach($errors->all() as $e)<p style="color:#b42318">{{ $e }}</p>@endforeach</div><div class="card"><h2>Expen